require_once '../inc/auth.php';require_once '../../config/koneksi.php';$title='Upload Foto';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$judul=trim($_POST['judul']??'');$des=trim($_POST['deskripsi']??'');if(empty($_FILES['foto']['name']))$error='Foto wajib dipilih.';if(!$error){require_once '../../inc/upload.php';$up=upload_image($_FILES['foto'],'../../uploads/galeri/');if(!$up['ok'])$error=$up['error'];else{$foto=$up['name'];$s=$conn->prepare("INSERT INTO galeri(judul,deskripsi,foto) VALUES(?,?,?)");$s->bind_param('sss',$judul,$des,$foto);$s->execute();header('Location:index.php');exit;}}}include '../inc/header.php';?><div class="page-title"><h1>Upload Foto Galeri</h1></div><div class="form-card"><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="form-group"><label>Judul</label><input name="judul" value="<?=htmlspecialchars($_POST['judul']??'')?>" placeholder="Contoh: Tanam Serempak Jagung"></div><div class="form-group"><label>Deskripsi</label><textarea name="deskripsi" placeholder="Keterangan foto..."><?=htmlspecialchars($_POST['deskripsi']??'')?></textarea></div><div class="form-group"><label>Foto</label><input type="file" name="foto" accept="image/jpeg,image/png,image/webp" required><p class="help">JPG/PNG/WEBP, maksimal 2 MB.</p></div><button class="btn green">Upload</button> <a class="btn gray" href="index.php">Batal</a></form></div><?php include '../inc/footer.php';?>